import{_ as t,o,c as a,a2 as d}from"./chunks/framework.DXa1R37q.js";const h=JSON.parse('{"title":"Claude Code","description":"","frontmatter":{},"headers":[],"relativePath":"harnesses/claude-code.md","filePath":"harnesses/claude-code.md","lastUpdated":1792947882000}'),r={name:"harnesses/claude-code.md"};function n(s,e,c,i,l,u){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="claude-code" tabindex="-1">Claude Code <a class="header-anchor" href="#claude-code" aria-label="Permalink to &quot;Claude Code&quot;">​</a></h1><p>Neottia compiles the canonical SDLC for Claude Code through <a href="https://www.npmjs.com/package/@neottia/claude-code-adapter" target="_blank" rel="noreferrer"><code>@neottia/claude-code-adapter</code></a>. The adapter declares documented Claude Code behavior and returns reviewable plans. It never writes files or runs the Claude Code binary.</p><h2 id="tested-support" tabindex="-1">Tested support <a class="header-anchor" href="#tested-support" aria-label="Permalink to &quot;Tested support&quot;">​</a></h2><p>The adapter projects these assets. Paths follow the <a href="https://docs.claude.com/en/docs/claude-code/overview" target="_blank" rel="noreferrer">Claude Code documentation</a>.</p><table tabindex="0"><thead><tr><th>Asset</th><th>Project</th><th>Global</th></tr></thead><tbody><tr><td>Command</td><td><code>.claude/commands/&lt;id&gt;.md</code></td><td><code>~/.claude/commands/&lt;id&gt;.md</code></td></tr><tr><td>Skill</td><td><code>.claude/skills/&lt;id&gt;/SKILL.md</code></td><td><code>~/.claude/skills/&lt;id&gt;/SKILL.md</code></td></tr><tr><td>Agent</td><td><code>.claude/agents/&lt;id&gt;.md</code></td><td><code>~/.claude/agents/&lt;id&gt;.md</code></td></tr><tr><td>MCP configuration</td><td><code>.mcp.json</code></td><td>Unsupported</td></tr></tbody></table><p>Command frontmatter supports <code>description</code>, <code>argument-hint</code>, <code>model</code>, and documented subagent routing. A portable subtask request maps to <code>context: fork</code>, and an explicit agent selection emits both <code>context: fork</code> and the documented <code>agent</code> field. Agent files support <code>name</code>, <code>description</code>, <code>model</code>, <code>effort</code>, and <code>maxTurns</code>. The portable per-tool permission map has no documented agent-file representation, so permission metadata returns a diagnostic instead of being dropped.</p><p>MCP plans target the committed project file <code>.mcp.json</code> under <code>mcpServers</code>. Local servers use the documented <code>type: &quot;stdio&quot;</code> shape with <code>command</code> and optional <code>args</code> and <code>env</code>; remote servers use <code>type: &quot;http&quot;</code> with <code>url</code> and optional <code>headers</code>. Per-server <code>timeout</code> values follow the documented minimum of 1000 milliseconds. The adapter does not edit user-managed state such as <code>~/.claude.json</code>, so MCP configuration is project-scoped only. Claude Code additionally requires interactive approval of project <code>.mcp.json</code> servers after installation.</p><h2 id="planned-support" tabindex="-1">Planned support <a class="header-anchor" href="#planned-support" aria-label="Permalink to &quot;Planned support&quot;">​</a></h2><ul><li>Runtime packages and plugin distribution. Neottia does not publish Claude Code plugins, and single-file extension requests cannot represent the multi-file plugin format. Package activation is unsupported today.</li><li>User-scope MCP configuration. The installer currently avoids host-managed files. A future release may add reviewed operations for user scope.</li><li>Other Copilot, Codex, and Kiro adapters. Research for issue <a href="https://github.com/dragoscirjan/neottia/issues/119" target="_blank" rel="noreferrer">#119</a> ranks GitHub Copilot CLI next; see <a href="/projects/neottia/harnesses/adapters">the adapter contract</a> for the shared rules every adapter follows.</li></ul><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><p>The compiler and installer apply the projected assets under your selected scope. After installation, restart Claude Code so commands, agents, and MCP configuration load together, then approve the project <code>.mcp.json</code> servers in the <code>/mcp</code> panel. The restart recommendation is Neottia adapter policy; Claude Code reloads some resources live but does not document one reload command for every asset type.</p><h2 id="authentication-and-configuration" tabindex="-1">Authentication and configuration <a class="header-anchor" href="#authentication-and-configuration" aria-label="Permalink to &quot;Authentication and configuration&quot;">​</a></h2><p>Claude Code manages its own sign-in, settings files, and OAuth for remote MCP servers. Neottia plans keep credential references such as <code>{env:ISSUES_TOKEN}</code> unresolved and never write authentication state. Configure the host authentication separately from Neottia installation.</p><p>The adapter does not list a tested Claude Code version because repository validation projects assets without executing the binary.</p>',14)])])}const m=t(r,[["render",n]]);export{h as __pageData,m as default};
